test('desktop initializes real five finger controls and capability gate',async()=>{const h=harness();await h.flush();assert.equal(h.nodes.fingers.children.length,5);assert.equal(h.nodes.upload.disabled,false);assert.match(h.nodes.connection.textContent,/USB COM3.*STS3032/);});
test('phone identifies hotspot and hides PC conversion without expecting bridge fields',async()=>{const h=harness({mobile:true});await h.flush();assert.match(h.nodes.connection.textContent,/手套热点.*STS3032/);assert.equal(h.nodes['convert-tab'].hidden,true);assert.equal(h.link.hidden,true);});
test('SC09 holds expose only zero or full and sensible labels',async()=>{const h=harness({model:'SC09'});await h.flush();assert.equal(h.nodes.hold.step,'100');assert.equal(h.nodes.hold.value,'100');h.nodes.hold.value='0';h.nodes.hold.oninput();assert.equal(h.nodes['hold-label'].textContent,'卸力');});
test('filesystem not ready keeps motion disabled',async()=>{const h=harness({ready:false});await h.flush();assert.equal(h.nodes.upload.disabled,true);assert.equal(h.nodes.fingers.children[0].disabled,true);assert.match(h.nodes.message.textContent,/存储尚未就绪/);});
test('heartbeat is sent only while local page owns active training',async()=>{const h=harness();await h.flush();const heart=h.intervals.find(x=>x.ms===500);await heart.f();assert.equal(h.sent.filter(x=>x.path==='/api/keep').length,0);await h.subject.train(1);await heart.f();assert.equal(h.sent.filter(x=>x.path==='/api/keep').length,1);await h.subject.stop();await heart.f();assert.equal(h.sent.filter(x=>x.path==='/api/keep').length,1);});
test('initializing pose makes no premature note sound',async()=>{const h=harness();await h.flush();await h.subject.getAudio();h.subject.setPlayback({notes:[{t_ms:0,duration_ms:500,pitch:60,finger:1}]},{active:true,initializing:true,elapsed_ms:0,tempo:100});h.subject.frame();assert.equal(h.sounds.length,0);});
test('long notes hold, rests release and same-pitch repeated notes retrigger',async()=>{const h=harness();await h.flush();await h.subject.getAudio();const score={notes:[{t_ms:0,duration_ms:300,pitch:60,finger:1},{t_ms:400,duration_ms:200,pitch:60,finger:1}]};h.subject.setPlayback(score,{active:true,elapsed_ms:0,tempo:100});h.subject.frame();assert.equal(h.subject.voiceCount,1);h.setNow(250);h.subject.frame();assert.equal(h.sounds.length,2);h.setNow(350);h.subject.frame();assert.equal(h.subject.voiceCount,0);h.setNow(450);h.subject.frame();assert.equal(h.subject.voiceCount,1);assert.equal(h.sounds.length,4);});
test('chords use independent voices and fingers',async()=>{const h=harness();await h.flush();await h.subject.getAudio();h.subject.setPlayback({notes:[{t_ms:0,duration_ms:100,pitch:60,finger:1},{t_ms:0,duration_ms:100,pitch:64,finger:3}]},{active:true,elapsed_ms:0,tempo:100});h.subject.frame();assert.equal(h.subject.voiceCount,2);});
test('tempo update uses returned continuous device elapsed clock',async()=>{const h=harness();await h.flush();await h.subject.getAudio();h.subject.setPlayback({notes:[{t_ms:0,duration_ms:600,pitch:60,finger:1},{t_ms:600,duration_ms:100,pitch:62,finger:2}]},{active:true,elapsed_ms:300,tempo:100});h.setState({active:true,elapsed_ms:300,tempo:200});h.nodes.tempo.value='200';await h.nodes.tempo.onchange();assert.ok(h.sent.some(x=>x.path==='/api/tempo'&&String(x.body)==='tempo=200'));h.setNow(100);h.subject.frame();assert.equal(h.subject.voiceCount,1);assert.ok(h.sounds[0]<270);h.setNow(170);h.subject.frame();assert.equal(h.subject.voiceCount,1);assert.ok(h.sounds[2]>280);});
test('pagehide sends stop, silences voices and halts heartbeat',async()=>{const h=harness({mobile:true});await h.flush();await h.subject.getAudio();await h.subject.train(1);h.events.pagehide();assert.equal(h.subject.active,false);assert.equal(h.subject.voiceCount,0);assert.ok(h.sent.some(x=>x.beacon&&x.path==='/api/stop'));const count=h.sent.length;await h.intervals.find(x=>x.ms===500).f();assert.equal(h.sent.length,count);});
test('device errors are human messages rather than protocol strings',async()=>{const h=harness();await h.flush();assert.equal(h.subject.friendly('ERR LIB TRAIN sc09_hold_supports_0_or_100'),'SC09 只支持卸力或保持');assert.equal(h.subject.friendly('ERR LIB PLAY other_internal_error'),'设备未完成操作，请停止后重试；具体原因尚未读到');});

test('late training response after stop cannot reactivate and only the ordered stop is sent',async()=>{const h=harness();await h.flush();await h.subject.getAudio();const previous=h.context.fetch;let resolve;h.context.fetch=async(url,opts)=>url==='/api/train'?await new Promise(r=>resolve=r):previous(url,opts);const pending=h.subject.train(1);await h.flush();const stopping=h.subject.stop();assert.equal(h.subject.active,false);resolve({ok:true,json:async()=>({ok:true})});await pending;await stopping;assert.equal(h.subject.active,false);assert.equal(h.subject.voiceCount,0);assert.equal(h.sent.filter(x=>x.path==='/api/stop').length,1);});
test('state polls do not overlap or accept a response from before stopping',async()=>{const h=harness();await h.flush();await h.subject.train(1);const previous=h.context.fetch;let resolve,count=0;h.context.fetch=async(url,opts)=>{if(url!=='/api/state')return previous(url,opts);count++;return new Promise(r=>resolve=r);};const poll=h.intervals.find(x=>x.ms===50),pending=poll.f();await poll.f();assert.equal(count,1);await h.subject.stop();resolve({ok:true,json:async()=>({active:true,mask:1,elapsed_ms:500,tempo:100})});await pending;assert.equal(h.subject.active,false);});

test('phone download reconstructs same PGL bytes as independent Python codec',async()=>{const h=harness({mobile:true});await h.flush();const score={version:1,hand:'right',title:'手机下载',duration_ms:200,notes:[{t_ms:0,duration_ms:200,pitch:60,finger:1,velocity:96,amplitude_pct:100}]};const bytes=h.subject.encodeScore(score);assert.equal(Buffer.from(bytes).toString('base64'),'UEdMMQEAgAABAAAAyAAAAN5eYTsMAAAA5omL5py65LiL6L29AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAyAAAADwBYGQAAAAA');});

async function recognizeFixture(h,hash='source-one',image='data:image/png;base64,known-source'){const previous=h.context.fetch;h.context.fetch=async(url,opts)=>url==='/api/software/convert'?{ok:true,json:async()=>({ok:true,project:{name:'原谱',source_sha256:hash,notes:[],selection:{},page_previews:[{page:1,data:image}]}})}:previous(url,opts);h.nodes.pdf.files=[{name:'原谱.pdf',arrayBuffer:async()=>new Uint8Array([37,80,68,70]).buffer}];await h.nodes.recognize.onclick();}
test('recognized response owns original SHA and mismatched review clears old page',async()=>{const h=harness();await h.flush();await recognizeFixture(h);assert.equal(h.nodes['original-image'].hidden,false);h.subject.loadReview({source_sha256:'different-source',notes:[],selection:{}});assert.equal(h.nodes['original-image'].hidden,true);assert.equal(h.nodes['original-empty'].hidden,false);});
test('matching review SHA preserves already rendered original instead of imported image',async()=>{const h=harness();await h.flush();await recognizeFixture(h,'same-source','data:image/png;base64,verified-original');h.subject.loadReview({source_sha256:'same-source',notes:[],selection:{},page_previews:[{page:1,data:'data:image/png;base64,unverified-import'}]});assert.equal(h.nodes['original-image'].hidden,false);assert.equal(h.nodes['original-image'].src,'data:image/png;base64,verified-original');});
test('review lacking a source SHA cannot reuse existing original picture',async()=>{const h=harness();await h.flush();await recognizeFixture(h);h.subject.loadReview({notes:[],selection:{}});assert.equal(h.nodes['original-image'].hidden,true);});
test('mobile switching app releases immediately and does not resume heartbeat',async()=>{const h=harness({mobile:true});await h.flush();await h.subject.getAudio();await h.subject.train(1);h.context.document.hidden=true;h.events.visibilitychange();assert.equal(h.subject.active,false);assert.equal(h.subject.voiceCount,0);assert.equal(h.sent.filter(x=>x.beacon).length,1);const count=h.sent.length;await h.intervals.find(x=>x.ms===500).f();assert.equal(h.sent.length,count);h.context.document.hidden=false;h.events.visibilitychange();assert.equal(h.subject.active,false);h.events.pagehide();assert.equal(h.sent.filter(x=>x.beacon).length,1);});

test('unknown beat shows written candidate as placeholder without filling or confirming',async()=>{const h=harness();await h.flush();for(const candidate of [0,7.25]){const note={id:1,page:1,hand:'right',pitch:'C4',finger:1,beat:null,duration_beats:1,written_beat:candidate,confirmed:false};h.subject.loadReview({notes:[note],selection:{}});const row=h.nodes['review-notes'].children[1],beat=row.children[3];assert.equal(beat.value,'');assert.equal(beat.placeholder,'候选 '+candidate);assert.equal(note.beat,null);assert.equal(note.confirmed,false);}});
test('reliable beat value does not get overwritten by written candidate',async()=>{const h=harness();await h.flush();const note={id:1,page:1,hand:'right',pitch:'C4',finger:1,beat:2,duration_beats:1,written_beat:9,confirmed:false};h.subject.loadReview({notes:[note],selection:{}});assert.equal(h.nodes['review-notes'].children[1].children[3].value,2);assert.equal(note.beat,2);});
test('changing any reviewed beat or page bound invalidates range confirmation',async()=>{const h=harness();await h.flush();h.subject.loadReview({notes:[],selection:{bpm:120,start_beat:0,end_beat:4,range_reviewed:true}});for(const id of ['start-beat','end-beat','start-page','end-page']){h.nodes['range-reviewed'].checked=true;h.nodes[id].value='2';h.nodes[id].oninput();assert.equal(h.nodes['range-reviewed'].checked,false);assert.equal(h.subject.selection().selection.range_reviewed,false);h.nodes['range-reviewed'].checked=true;h.nodes[id].onchange();assert.equal(h.nodes['range-reviewed'].checked,false);}});

test('feedback arm failure identifies the correct finger and real cause',async()=>{const h=harness();await h.flush();assert.equal(h.subject.friendly('stage=feedback_outside slot=2 id=3 observed=2522 expected=-1 bus_error=0 speed=1200 acc=30'),'食指当前位置超出校准允许余量，先回到范围内再试（当前位置 2522）；动作已停止');assert.match(h.subject.friendly('stage=feedback_read slot=4 id=5 observed=-1 expected=-1'),/无名指.*反馈未读到/);assert.match(h.subject.friendly('stage=hardware_limits_invalid slot=0 id=1'),/拇指侧摆.*舵机允许范围/);});
