test('active state timer requests every 50ms but never overlaps a pending response',async()=>{const h=harness();await h.flush();await h.subject.train(1);h.setState({active:true,mode:'train',mask:1});const poll=h.intervals.find(x=>x.ms===50);h.setNow(0);await poll.f();h.setNow(49);await poll.f();assert.equal(h.sent.filter(x=>x.path==='/api/state').length,1);h.setNow(50);await poll.f();assert.equal(h.sent.filter(x=>x.path==='/api/state').length,2);const previous=h.context.fetch;let reply,count=0;h.context.fetch=async(url,opts)=>{if(url==='/api/state'){count++;return new Promise(r=>reply=r);}return previous(url,opts);};h.setNow(100);const pending=poll.f();h.setNow(150);await poll.f();h.setNow(200);await poll.f();assert.equal(count,1);reply({ok:true,json:async()=>({active:true,mode:'train',mask:1})});await pending;h.setNow(250);const next=poll.f();assert.equal(count,2);reply({ok:true,json:async()=>({active:true,mode:'train',mask:1})});await next;});
