test('a paused feedback update can correct old elapsed overshoot and resume only the next acknowledged note',async()=>{const h=harness();await h.flush();await h.subject.getAudio();const notes=[{t_ms:0,duration_ms:200,pitch:60,finger:1},{t_ms:200,duration_ms:200,pitch:62,finger:2},{t_ms:400,duration_ms:200,pitch:64,finger:3}];h.subject.setPlayback({notes},{active:true,elapsed_ms:0,tempo:100});h.setNow(450);h.subject.frame();assert.ok(h.sounds.at(-2)>325);h.setState({active:true,elapsed_ms:199,tempo:200,clock_paused:true,clock_limit_ms:200,mask:1});await h.subject.sampleState();h.subject.frame();assert.equal(h.subject.voiceCount,1);assert.deepEqual(Array.from(h.subject.activePitches),[60]);const held=h.sounds.length;h.setNow(1000);h.subject.frame();assert.equal(h.sounds.length,held);h.setState({active:true,elapsed_ms:210,tempo:200,clock_paused:false,clock_limit_ms:400,mask:2});await h.subject.sampleState();h.subject.frame();assert.equal(h.subject.voiceCount,1);assert.deepEqual(Array.from(h.subject.activePitches),[62]);});
