test('genuine original page and optional original coordinates follow the matching note only',async()=>{const h=harness();await h.flush();h.nodes['player-source-image'].clientHeight=2000;h.nodes['player-source'].clientHeight=400;h.subject.openPlayer({title:'原谱',notes:[{t_ms:0,duration_ms:1000,pitch:60,finger:1}],source_preview:{available:true,pages:[{page:1,width:1000,height:2000,image_url:'/api/software/source/known/1'},{page:2,width:1000,height:2000,image_url:'/api/software/source/known/2'}],note_pages:[{index:0,page:2,x:200,y:400,width:100,height:50}]}});h.subject.renderPlayer(100);assert.equal(h.nodes['player-source-label'].textContent,'原谱');assert.equal(h.nodes['player-source-image'].src,'/api/software/source/known/2');assert.equal(h.nodes['player-source-cursor'].style.left,'20%');assert.equal(h.nodes['player-source-cursor'].style.top,'20%');assert.equal(h.nodes['player-source-cursor'].hidden,false);assert.equal(h.nodes['player-source'].scrollTop,225);h.nodes['player-source-image'].onerror();assert.equal(h.nodes['player-source'].hidden,true);assert.equal(h.nodes['player-source-label'].textContent,'音符进度');assert.equal(h.nodes['player-source-hint'].hidden,false);});
test('unassociated or arbitrary remote pictures never become an original score',async()=>{const h=harness();await h.flush();for(const source_preview of [undefined,{available:false,pages:[]},{available:true,pages:[{page:1,image_url:'https://unverified.example/score.png'}]}]){h.subject.openPlayer({notes:[],source_preview});assert.equal(h.nodes['player-source'].hidden,true);assert.equal(h.nodes['player-source-label'].textContent,'音符进度');assert.equal(h.nodes['player-source-hint'].hidden,false);}});
test('local audio scheduler runs without any animation frame or per-note HTTP write',async()=>{const h=harness();await h.flush();await h.subject.getAudio();h.subject.setPlayback({notes:[{t_ms:100,duration_ms:300,pitch:62,finger:2}]},{active:true,elapsed_ms:0,tempo:100,clock_limit_ms:400});const count=h.sent.length;h.setNow(40);await h.intervals.find(t=>t.ms===20).f();assert.equal(h.sounds.length,2);assert.equal(h.sent.length,count);});
test('all requests retain one controller header and pagehide beacon carries the same token',async()=>{const h=harness();await h.flush();await h.subject.train(1);const headers=h.sent.filter(x=>!x.beacon).map(x=>x.headers['X-Piano-Controller']);assert.ok(headers[0]);assert.ok(headers.every(x=>x===headers[0]));h.events.pagehide();const body=await h.sent.find(x=>x.beacon).body.text();assert.equal(new URLSearchParams(body).get('controller'),headers[0]);});
test('a controller mismatch cancels local sound without issuing STOP against the other page',async()=>{const h=harness();await h.flush();const before=h.sent.length;h.context.fetch=async(url,opts)=>{h.sent.push({path:url,body:opts.body});return {ok:false,json:async()=>({error:'controller_mismatch'})};};await assert.rejects(h.subject.train(1),/controller_mismatch/);assert.equal(h.subject.active,false);assert.equal(h.subject.voiceCount,0);assert.equal(h.sent.slice(before).filter(x=>x.path==='/api/stop').length,0);assert.match(h.nodes.message.textContent,/另一页面正在控制/);});
test('advertised chunk upload sends bounded bytes then commit without complete-file fallback',async()=>{const h=harness();await h.flush();h.subject.setUploadCapabilities({upload_protocol:'chunks-v1',upload_chunk_max:384});h.nodes.pgl.files=[{arrayBuffer:async()=>new Uint8Array(1000).buffer}];h.nodes.slot.value='7';await h.nodes.upload.onclick();const writes=h.sent.filter(x=>x.path.startsWith('/api/upload'));assert.deepEqual(writes.map(x=>x.path),['/api/upload/begin','/api/upload/chunk','/api/upload/chunk','/api/upload/chunk','/api/upload/commit']);assert.equal(new URLSearchParams(writes[0].body).get('bytes'),'1000');assert.equal(new URLSearchParams(writes[0].body).get('slot'),'7');assert.deepEqual(writes.filter(x=>x.path.endsWith('chunk')).map(x=>x.body.byteLength),[384,384,232]);assert.match(h.nodes.message.textContent,/已写入/);assert.equal(h.nodes.upload.disabled,false);});
test('failed chunk aborts pending upload and never commits or starts motion',async()=>{const h=harness();await h.flush();h.subject.setUploadCapabilities({upload_protocol:'chunks-v1',upload_chunk_max:384});h.nodes.pgl.files=[{arrayBuffer:async()=>new Uint8Array(1000).buffer}];const previous=h.context.fetch;h.context.fetch=async(url,opts)=>{if(url==='/api/upload/chunk'){h.sent.push({path:url,body:opts.body});return {ok:false,json:async()=>({error:'upload_crc_error'})};}return previous(url,opts);};await h.nodes.upload.onclick();assert.equal(h.sent.filter(x=>x.path==='/api/upload/abort').length,1);assert.equal(h.sent.filter(x=>x.path==='/api/upload/commit'||x.path==='/api/play'||x.path==='/api/train').length,0);assert.equal(h.nodes.upload.disabled,false);});
test('stop during a delayed chunk orders abort after the response and never continues uploading',async()=>{const h=harness();await h.flush();h.subject.setUploadCapabilities({upload_protocol:'chunks-v1',upload_chunk_max:384});h.nodes.pgl.files=[{arrayBuffer:async()=>new Uint8Array(1000).buffer}];const previous=h.context.fetch;let reply;h.context.fetch=async(url,opts)=>{if(url==='/api/upload/chunk'){h.sent.push({path:url,body:opts.body});return new Promise(r=>reply=r);}return previous(url,opts);};const uploading=h.nodes.upload.onclick();await h.flush();const stopping=h.subject.stop();await h.flush();assert.equal(h.sent.filter(x=>x.path==='/api/upload/abort').length,0);reply({ok:true,json:async()=>({ok:true})});await uploading;await stopping;assert.deepEqual(h.sent.filter(x=>x.path.startsWith('/api/upload')).map(x=>x.path),['/api/upload/begin','/api/upload/chunk','/api/upload/abort']);assert.equal(h.sent.at(-1).path,'/api/stop');});
test('repeat and tie expansion remain manual review choices and edits revoke their confirmation',async()=>{const h=harness();await h.flush();h.subject.loadReview({notes:[{id:1,page:1,pitch:'C4',finger:1,beat:0,duration_beats:1,tie_to_candidate:2},{id:2,page:1,pitch:'C4',finger:1,beat:1,duration_beats:1}],repeat_sections:[{start_beat:0,end_beat:2,count:2}],selection:{}});assert.equal(h.nodes['notation-options'].hidden,false);assert.equal(h.nodes['repeat-unfold'].checked,false);assert.equal(h.nodes['tie-apply'].checked,false);h.nodes['repeat-unfold'].checked=true;h.nodes['repeat-unfold'].onchange();h.nodes['tie-apply'].checked=true;h.nodes['tie-apply'].onchange();assert.equal(h.nodes['repeats-reviewed'].checked,false);assert.equal(h.nodes['ties-reviewed'].checked,false);h.nodes['repeats-reviewed'].checked=true;h.nodes['ties-reviewed'].checked=true;const saved=h.subject.selection();assert.equal(saved.selection.repeat_mode,'unfold');assert.equal(saved.selection.apply_tie_candidates,true);h.subject.loadReview(JSON.parse(JSON.stringify(saved)));assert.equal(h.nodes['repeats-reviewed'].checked,true);assert.equal(h.nodes['ties-reviewed'].checked,true);const duration=h.nodes['review-notes'].children[1].children[4];duration.value='2';duration.onchange();assert.equal(h.nodes['repeats-reviewed'].checked,false);assert.equal(h.nodes['ties-reviewed'].checked,false);});
