const recoveredStatus={bridge:1,connected:true,port:'COM7',device_info:'model=SC09',upload_protocol:'chunks-v1',upload_chunk_max:2};
const recoveredLibrary={ready:true,count:1,max:100,free:8192,slots:[{slot:4,title:'重连后的曲谱',notes:2,duration_ms:1000,stored:160}]};
const readCount=(h,url)=>h.sent.filter(x=>x.path===url).length;
const automaticMotionWrites=h=>h.sent.filter(x=>/^\/api\/(train|play|pattern|keep)(?:$|\?)/.test(x.path));
async function freshRecovery(h,now=2101){h.setNow(now);h.setState({active:false,model:'SC09',encoder_range:1023,feedback:[freshAxis(500)]});await h.subject.sampleState();await h.flush();}
async function expireConnection(h){h.setState({active:false,encoder_range:4095,feedback:[freshAxis(2171)]});await h.subject.sampleState();h.setNow(1101);h.subject.expireFeedback();assert.equal(h.nodes.fingers.children[0].disabled,true);}

for(const [startup,initialStatus] of [['disconnected',{bridge:1,connected:false,port:null}],['failed',new Error('Failed to fetch')]]){
 test(`reconnection after ${startup} initialization restores identity, capabilities and library without reload`,async()=>{
  const h=harness({initialStatus,initialLibrary:{ready:false}});await h.flush();
  assert.equal(h.nodes.upload.disabled,true);assert.equal(h.nodes.fingers.children[0].disabled,true);
  h.setStatus(recoveredStatus);h.setLibrary(recoveredLibrary);await freshRecovery(h);
  assert.match(h.nodes.connection.textContent,/USB COM7.*SC09.*已就绪/);assert.doesNotMatch(h.nodes.connection.textContent,/未连接|手套热点|连接中断/);
  assert.equal(h.nodes['convert-tab'].hidden,false);assert.equal(h.link.hidden,false);assert.equal(h.nodes.hold.step,'100');
  assert.equal(h.nodes.activity.textContent,'待机');assert.match(h.nodes.capacity.textContent,/已存 1 \/ 100 首/);
  assert.match(h.nodes.songs.children[0].children[0].textContent,/重连后的曲谱/);assert.equal(h.nodes.upload.disabled,false);assert.equal(h.nodes.fingers.children[0].disabled,false);
  assert.equal(h.subject.active,false);assert.equal(automaticMotionWrites(h).length,0);
  // Exercise recovered protocol capabilities against this harness's mock fetch only.
  h.nodes.pgl.files=[{name:'mock.pgl',arrayBuffer:async()=>new Uint8Array([80,71,76,49]).buffer}];h.nodes.slot.value='1';await h.nodes.upload.onclick();
  assert.equal(readCount(h,'/api/upload/begin'),1);assert.equal(readCount(h,'/api/upload/chunk'),2);assert.equal(readCount(h,'/api/upload/commit'),1);
 });
}
