 const h=harness();await h.flush();await expireConnection(h);let completeStatus;h.setStatus(()=>new Promise(resolve=>completeStatus=resolve));h.setLibrary(recoveredLibrary);
 await freshRecovery(h);assert.equal(typeof completeStatus,'function');h.setState({active:false,feedback:[{id:2,position:500,position_valid:false,sample_age_ms:0}]});completeStatus(recoveredStatus);await h.flush();
 assert.equal(h.nodes.fingers.children[0].disabled,true);assert.equal(h.nodes.upload.disabled,true);assert.doesNotMatch(h.nodes.connection.textContent,/已就绪/);
