test('reconnect metadata is single-flight and failed reads are throttled until a later fresh packet',async()=>{
 const h=harness();await h.flush();await expireConnection(h);let rejectStatus;h.setStatus(()=>new Promise((resolve,reject)=>rejectStatus=reject));
 const statuses=readCount(h,'/api/software/status');await freshRecovery(h);assert.equal(readCount(h,'/api/software/status'),statuses+1);
 for(const now of [2200,2600,3000])await freshRecovery(h,now);
 assert.equal(readCount(h,'/api/software/status'),statuses+1);assert.equal(h.nodes.fingers.children[0].disabled,true);
 rejectStatus(Error('Failed to fetch'));await h.flush();h.setStatus(recoveredStatus);h.setLibrary(recoveredLibrary);
 for(const now of [3100,3500,4000])await freshRecovery(h,now);
 assert.equal(readCount(h,'/api/software/status'),statuses+1);assert.equal(h.nodes.fingers.children[0].disabled,true);
 await freshRecovery(h,4200);assert.equal(readCount(h,'/api/software/status'),statuses+2);assert.equal(h.nodes.fingers.children[0].disabled,false);
 assert.equal(automaticMotionWrites(h).length,0);
});
for(const pendingEndpoint of ['status','library']){
 test(`late reconnect ${pendingEndpoint} cannot overwrite a newer disconnect or leave recovery stuck`,async()=>{
  const h=harness();await h.flush();await expireConnection(h);let complete;
  h.setStatus(pendingEndpoint==='status'?()=>new Promise(resolve=>complete=resolve):recoveredStatus);
  h.setLibrary(pendingEndpoint==='library'?()=>new Promise(resolve=>complete=resolve):recoveredLibrary);
  await freshRecovery(h);assert.equal(typeof complete,'function');assert.equal(h.nodes.fingers.children[0].disabled,true);
  const previous=h.context.fetch;h.context.fetch=async(url,opts)=>{if(url==='/api/state')throw Error('Failed to fetch');return previous(url,opts);};h.setNow(3202);await h.intervals.find(x=>x.ms===50).f();const connection=h.nodes.connection.textContent,capacity=h.nodes.capacity.textContent;
  assert.match(connection,/连接中断/);complete(pendingEndpoint==='status'?recoveredStatus:recoveredLibrary);await h.flush();
  assert.equal(h.nodes.connection.textContent,connection);assert.equal(h.nodes.capacity.textContent,capacity);assert.equal(h.nodes.fingers.children[0].disabled,true);
  assert.equal(h.nodes.upload.disabled,true);assert.equal(h.subject.active,false);
  h.context.fetch=previous;h.setStatus(recoveredStatus);h.setLibrary(recoveredLibrary);await freshRecovery(h,5500);
  assert.match(h.nodes.connection.textContent,/USB COM7.*SC09.*已就绪/);assert.equal(h.nodes.fingers.children[0].disabled,false);assert.equal(automaticMotionWrites(h).length,0);
 });
}
